	private static List<String> firstRow(Kernel ir, NativeAdjacency source, KernelHooks hooks, boolean compiled)
			throws Exception {
		JaninoKernel execution = compiled ? KernelCompilationTestSupport.compile(ir)
				: LmdbNativeKernelInterpreter.forRows(ir);
		assertNotNull(execution);
		try {
			execution.bind(new KernelContext(new NativeAdjacency[] { source }, new long[] { 10 }, new long[0],
					new long[0][], hooks));
			long[] row = new long[ir.stride()];
			assertEquals(1, execution.fill(row, 1));
			return List.of(Arrays.toString(row));
		} finally {
			execution.close();
		}
	}

	private static KernelWorkCounters executeWithWork(Kernel ir, Wildcard source, KernelHooks hooks, boolean compiled,
			int expectedRows) throws Exception {
		return executeWithWork(ir, source, hooks, compiled, null, expectedRows);
	}

	private static KernelWorkCounters executeWithWork(Kernel ir, Wildcard source, KernelHooks hooks, boolean compiled,
			List<String> expected) throws Exception {
		return executeWithWork(ir, source, hooks, compiled, expected, expected.size());
	}

	private static KernelWorkCounters executeWithWork(Kernel ir, Wildcard source, KernelHooks hooks, boolean compiled,
			List<String> expected, int expectedRows) throws Exception {
		JaninoKernel execution = compiled ? KernelCompilationTestSupport.compile(ir)
				: ir.terminal instanceof Aggregate ? LmdbNativeKernelInterpreter.forAggregate(ir)
						: LmdbNativeKernelInterpreter.forRows(ir);
		assertNotNull(execution);
		try {
			execution.bind(
					new KernelContext(new NativeAdjacency[0], new long[] { 10 }, new long[0], new long[0][], hooks,
							null, null, 16, null, null, new WildcardAdjacency[] { source }));
			List<String> rows = fillRows(execution, ir.stride());
			assertEquals(expectedRows, rows.size());
			if (expected != null) {
				assertEquals(expected, rows);
			}
		} finally {
			execution.close();
		}
		KernelWorkCounters work = execution.workCounters();
		assertNotNull(work);
		return work;
	}

	@ParameterizedTest(name = "compiled={0}")
	@ValueSource(booleans = { false, true })
	void onePresenceWitnessCannotBeReinterpretedAsOneWitnessPerPage(boolean compiled) throws Exception {
		Kernel ir = new Kernel(3, List.of(
				new EnumerateWildcard(0, true, LmdbWildcardPhysicalDemand.Demand.PAIR_PRESENCE,
						1, 0, 2, -1, null, false),
				new FilterValue(0, new Operand[] { Operand.col(1), Operand.col(0) }, true)),
				new Aggregate(new int[0], new AggregateOutput[] { AggregateOutput.countStar() }, null,
						OutputMods.none()));
		PredicateHooks fullHooks = new PredicateHooks(ignored -> true);
		AtomicInteger pageOpens = new AtomicInteger();
		Wildcard full = splitRootFixture(new CyclicBarrier(1), pageOpens);
		assertEquals(List.of("[1]"), runWildcard(ir, full, fullHooks, compiled),
				"one root remains one presence witness although its ten physical quads span two pages");
		assertEquals(1, fullHooks.calls[0]);
		for (int page = 0; page < 2; page++) {
			Wildcard source = splitRootFixture(new CyclicBarrier(1), pageOpens);
			WildcardAdjacency fragment = new LmdbNativeKernelPartitions.WildcardPageWindow(source, 0, page,
					page + 1L);
			PredicateHooks hooks = new PredicateHooks(ignored -> true);
			assertThrows(LmdbNativeKernelPartitions.ParallelKernelDecline.class,
					() -> runWildcard(ir, fragment, hooks, compiled),
					"a partial page cannot certify a complete-root presence witness for independent publication");
			assertEquals(0, hooks.calls[0], "an unavailable whole-root recipe declines before invoking its callback");
		}
		assertEquals(0, pageOpens.get(), "presence uses a complete root cursor rather than additive page weights");
	}

	@ParameterizedTest(name = "compiled={0}, restricted contexts={1}")
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void twoActualPageWindowWorkersUseOnlyTheirVisibleRootMultiplicity(boolean compiled, boolean restricted)
			throws Exception {
		WorkerWindows payload = runPageWindows(compiled, restricted, LmdbWildcardPhysicalDemand.Demand.PAYLOAD);
		List<String> expected = restricted ? List.of("[2, 2]", "[4, 4]") : List.of("[3, 3]", "[7, 7]");
		assertEquals(expected, payload.rows, "PAYLOAD preflight proves two exact fragments of the same root");
		assertEquals(2, payload.workers.size(), "both real workers must cross the execution barriers");
		assertEquals(2, payload.pageOpens);
		WorkerWindows compressed = assertDoesNotThrow(
				() -> runPageWindows(compiled, restricted, LmdbWildcardPhysicalDemand.Demand.PAIR_MULTIPLICITY),
				"an admitted compressed page window must not expand or count the whole root in each worker");
		assertEquals(expected, compressed.rows);
		assertEquals(2, compressed.workers.size());
		assertEquals(2, compressed.pageOpens);
		assertEquals(2, compressed.predicateCalls, "the predicate is local to each actually visible root fragment");
	}

