	@ParameterizedTest(name = "compiled={0}, demand={1}")
	@CsvSource({ "false,NODE_ANY", "false,PREDICATE_ANY", "false,PAIR_PRESENCE", "false,PAIR_MULTIPLICITY",
			"false,PAYLOAD", "true,NODE_ANY", "true,PREDICATE_ANY", "true,PAIR_PRESENCE",
			"true,PAIR_MULTIPLICITY", "true,PAYLOAD" })
	void eachDemandReusesOnlyCoordinatesActuallySuppliedByItsProducer(boolean compiled,
			LmdbWildcardPhysicalDemand.Demand demand) throws Exception {
		EnumerateWildcard producer = new EnumerateWildcard(0, true, demand, 1, 0, 2, -1, null, false);
		Operand[] args = demand == LmdbWildcardPhysicalDemand.Demand.NODE_ANY
				|| demand == LmdbWildcardPhysicalDemand.Demand.PREDICATE_ANY ? new Operand[0]
						: demand == LmdbWildcardPhysicalDemand.Demand.PAIR_PRESENCE
								? new Operand[] { Operand.col(0) }
								: new Operand[] { Operand.col(1), Operand.col(0) };
		int[] output = demand == LmdbWildcardPhysicalDemand.Demand.NODE_ANY ? new int[] { 3 }
				: demand == LmdbWildcardPhysicalDemand.Demand.PREDICATE_ANY ? new int[] { 0 }
						: demand == LmdbWildcardPhysicalDemand.Demand.PAYLOAD ? new int[] { 0, 1, 2 }
								: new int[] { 0, 1 };
		List<Node> ordinaryNodes = List.of(producer, new BindAlias(Operand.constant(0), 3),
				new FilterValue(0, args, false));
		Kernel ordinary = new Kernel(4, ordinaryNodes, emit(output));
		PredicateHooks ordinaryHooks = new PredicateHooks(ignored -> true);
		List<String> reference = runWildcard(ordinary, wildcardFixture(), ordinaryHooks, compiled);
		int rows = switch (demand) {
		case NODE_ANY -> 1;
		case PREDICATE_ANY -> 2;
		case PAIR_PRESENCE -> 4;
		case PAIR_MULTIPLICITY, PAYLOAD -> 10;
		};
		assertEquals(rows, reference.size());
		assertEquals(rows, ordinaryHooks.calls[0]);
		Kernel scheduled = new Kernel(4, List.of(producer, new BindAlias(Operand.constant(0), 3),
				new FilterValue(0, args, true)), emit(output));
		PredicateHooks hooks = new PredicateHooks(ignored -> true);

		assertEquals(reference, runWildcard(scheduled, wildcardFixture(), hooks, compiled));
		assertEquals(demand == LmdbWildcardPhysicalDemand.Demand.NODE_ANY
				|| demand == LmdbWildcardPhysicalDemand.Demand.PREDICATE_ANY ? 1
						: demand == LmdbWildcardPhysicalDemand.Demand.PAIR_PRESENCE ? 2 : 4,
				hooks.calls[0]);
		if (demand == LmdbWildcardPhysicalDemand.Demand.PAIR_PRESENCE) {
			assertEquals(List.of("7:-1", "9:-1"), hooks.arguments);
		}
	}

