	@ParameterizedTest(name = "compiled={0}, empty source={1}")
	@CsvSource({ "false,0", "false,1", "false,2", "false,3", "true,0", "true,1", "true,2", "true,3" })
	void inputProgramsWaitForAnActualVisibleProducerWitness(boolean compiled, int sourceKind) throws Exception {
		Adjacency source = sourceKind == 2 ? fixture()
				: new Adjacency(new long[0], new long[0][], new long[0][]);
		WildcardAdjacency wildcard = sourceKind == 0 ? new Wildcard(new long[0], new Adjacency[0])
				: new Wildcard(new long[] { 7 }, new Adjacency[] { source });
		Node producer = switch (sourceKind) {
		case 0, 1 -> new EnumerateWildcard(0, true, LmdbWildcardPhysicalDemand.Demand.PAYLOAD, 0, 2, 1,
				-1, null, false);
		case 2 -> new EnumerateAdjKeys(0, 0, 1, -1, Operand.constant(0), false);
		case 3 -> new Probe(0, Operand.constant(0), 1);
		default -> throw new AssertionError("unknown fixture kind");
		};
		PredicateHooks ordinaryHooks = new PredicateHooks(ignored -> true);
		Kernel ordinary = new Kernel(3, List.of(producer, new FilterValue(0, new Operand[0], false)), emit(0, 1));
		assertEquals(List.of(), run(ordinary, source, wildcard, ordinaryHooks, compiled));
		assertEquals(0, ordinaryHooks.calls[0], "the original continuation has no visible mapping to evaluate");
		PredicateHooks hooks = new PredicateHooks(ignored -> true);
		Kernel scheduled = new Kernel(3, List.of(producer, new FilterValue(0, new Operand[0], true)), emit(0, 1));

		assertEquals(List.of(), run(scheduled, source, wildcard, hooks, compiled));
		assertEquals(0, hooks.calls[0], "an empty catalog, plane, graph restriction or probe has no INPUT callback");
	}

