	@ParameterizedTest(name = "compiled={0}, effect={1}")
	@CsvSource({ "false,PURE", "false,ROW_STABLE", "false,VOLATILE", "true,PURE", "true,ROW_STABLE",
			"true,VOLATILE" })
	void realLoweringSeparatesWorkerBindingFromCrossMappingPredicateReplay(boolean compiled, EffectClass effect)
			throws Exception {
		ValueExpr expression = switch (effect) {
		case PURE -> new Bound(new Var("root"));
		case ROW_STABLE -> new IsBNode(new BNodeGenerator(new Str(new Var("root"))));
		case VOLATILE -> new And(new Bound(new Var("root")), new IsBNode(new BNodeGenerator()));
		default -> throw new AssertionError("unsupported fixture effect");
		};
		NativeScalarPlan scalar = NativeScalarPlan.create(expression, name -> 0, NativeScalarPlan.ResultKind.BOOLEAN,
				false, 1L, true, true);
		assertNotNull(scalar);
		assertEquals(effect, scalar.effect());
		assertTrue(scalar.workerBindable(), "the regression distinguishes worker binding from row replay");
		AtomicInteger calls = new AtomicInteger();
		LmdbNativeCompiledBoolean filter = new LmdbNativeCompiledBoolean(1L, ignored -> {
			calls.incrementAndGet();
			return LmdbNativeTruth.TRUE;
		}, scalar);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("root", 0, "neighbor", 1), null);
		layout.freeze(List.of("root", "neighbor"));
		RowState row = new RowState(new ScheduleSource(), layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(7L), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 5D);
		var lowered = LmdbNativeKernelLowering.lowerRows(new FilterPlan(pattern, filter, 1L), row, null);
		assertNotNull(lowered, "the actual filter/producer pair must lower before callback-count assertions");
		LmdbNativeKernelHooks hooks = new LmdbNativeKernelHooks(row, lowered.bindings);
		JaninoKernel execution = compiled ? KernelCompilationTestSupport.compile(lowered.kernel)
				: LmdbNativeKernelInterpreter.forRows(lowered.kernel);
		assertNotNull(execution);
		try {
			execution.bind(new KernelContext(new NativeAdjacency[] { fixture() }, lowered.bindings.constants,
					new long[0], new long[0][], hooks));
			assertEquals(5, fillRows(execution, lowered.kernel.stride()).size());
			assertEquals(effect == EffectClass.PURE ? 2 : 5, calls.get(),
					"repeatable worker rebinding cannot turn ROW_STABLE or VOLATILE work into root reuse");
		} finally {
			execution.close();
			hooks.closeFilters();
		}
	}

